function requestVote(){if(!s||!me?.alive||s.ready.includes(s.owner))return;update(x=>{const ready=[...new Set([...x.ready,x.owner,...x.players.filter(p=>p.bot&&p.alive).filter((p,i)=>(i+x.day)%3!==0).map(p=>p.id)])];return {...x,ready,phase:ready.length>Math.floor(x.players.filter(p=>p.alive).length/2)?'vote':'discussion',messages:[...x.messages,{id:id(),by:x.owner,day:x.day,kind:'request',text:'Tražim da se glasa!'}],actions:[...x.actions,log(x,x.owner,`Predložio/la početak glasanja (${ready.length} podrški)`,'vote')]}})}
