function randomEncounter(){if(!s)return;const eligible=s.players.filter(p=>p.alive&&p.id!==s.owner);if(!eligible.length)return;const recipient=eligible[(s.day+s.messages.length+s.actions.length)%eligible.length].id;setPrivateTo(recipient);setDraft('');setTab('main');say('Privatni susret je počeo. Napiši poruku osobi koja te čeka.');update(x=>{const others=x.players.filter(p=>p.alive&&p.id!==x.owner);if(!others.length)return x;const other=others[(x.day+x.messages.length+x.actions.length)%others.length];return {...x,activeEncounter:other.id,encounters:[...(x.encounters||[]),{a:x.owner,b:other.id,day:x.day}],messages:[...x.messages,{id:id(),by:other.id,day:x.day,kind:'private',to:x.owner,text:`Sreli smo se u hodniku. Šta misliš o današnjoj misiji?`},{id:id(),by:'system',day:x.day,kind:'encounter',text:`👀 ${x.players.find(p=>p.id===x.owner)?.name} i ${other.name} viđeni su u privatnom razgovoru.`}],actions:[...x.actions,log(x,'system',`${x.players.find(p=>p.id===x.owner)?.name} i ${other.name} razgovaraju nasamo`,'encounter')]}})}
function dayConsent(){if(!s?.privateConversationDone){say('Prije okruglog stola moraš obaviti barem jedan privatni razgovor.');return;}update(x=>{const ready=[...new Set([...(x.dayReady||[]),x.owner,...x.players.filter(p=>p.alive&&p.bot).filter((p,i)=>(i+x.day)%4!==0).map(p=>p.id)])];const majority=ready.length> x.players.filter(p=>p.alive).length/2;return {...x,dayReady:ready,phase:majority?'discussion':x.phase,discussionStartedAt:majority?Date.now():x.discussionStartedAt,actions:[...x.actions,log(x,x.owner,majority?'Većina je spremna za okrugli sto':'Traži završetak dnevnog druženja','ready')]}})}
